import https from 'https';

export interface LiveMarketStats {
  source: 'binance' | 'coingecko' | 'fallback';
  priceUsd: number;
  change24hPct: number;
  high24h?: number;
  low24h?: number;
  volumeUsd?: number;
  marketCapUsd?: number;
}

let cachedBtcPrice: { price: number; timestamp: number } = { price: 80550, timestamp: 0 };

function fetchHttpsJson(url: string, timeoutMs = 4000): Promise<any> {
  return new Promise((resolve) => {
    const req = https.get(
      url,
      { headers: { 'User-Agent': 'Mozilla/5.0 (CryptoInstitutional/1.0)' }, timeout: timeoutMs },
      (res) => {
        if (res.statusCode !== 200) {
          return resolve(null);
        }
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          try {
            resolve(JSON.parse(data));
          } catch {
            resolve(null);
          }
        });
      }
    );
    req.on('error', () => resolve(null));
    req.on('timeout', () => {
      req.destroy();
      resolve(null);
    });
  });
}

/**
 * Fetch current Bitcoin price in USD for exact Coin/BTC ratio calculation
 */
export async function getLiveBtcPrice(): Promise<number> {
  const now = Date.now();
  if (cachedBtcPrice.timestamp && now - cachedBtcPrice.timestamp < 15000) {
    return cachedBtcPrice.price;
  }

  const binanceBtc = await fetchHttpsJson('https://api.binance.com/api/v3/ticker/24hr?symbol=BTCUSDT', 3000);
  if (binanceBtc && binanceBtc.lastPrice) {
    const p = parseFloat(binanceBtc.lastPrice);
    if (!isNaN(p) && p > 1000) {
      cachedBtcPrice = { price: p, timestamp: now };
      return p;
    }
  }

  return cachedBtcPrice.price || 80550;
}

/**
 * Universal online cryptocurrency price fetcher
 * Resolves real market price, 24h change, high, low, volume for ANY coin
 */
export async function fetchOnlineCoinStats(
  ticker: string,
  defaultPrice: number
): Promise<LiveMarketStats> {
  const sym = ticker.toUpperCase().trim();

  // 1. Check Binance USDT pair
  const binanceData = await fetchHttpsJson(`https://api.binance.com/api/v3/ticker/24hr?symbol=${sym}USDT`, 3500);
  if (binanceData && binanceData.lastPrice) {
    const p = parseFloat(binanceData.lastPrice);
    const chg = parseFloat(binanceData.priceChangePercent);
    const hi = parseFloat(binanceData.highPrice);
    const lo = parseFloat(binanceData.lowPrice);
    const vol = parseFloat(binanceData.quoteVolume || binanceData.volume);

    if (!isNaN(p) && p > 0) {
      return {
        source: 'binance',
        priceUsd: p,
        change24hPct: isNaN(chg) ? 0 : parseFloat(chg.toFixed(2)),
        high24h: isNaN(hi) ? undefined : hi,
        low24h: isNaN(lo) ? undefined : lo,
        volumeUsd: isNaN(vol) ? undefined : vol
      };
    }
  }

  // 2. If not on Binance USDT, try CoinGecko search & simple price
  try {
    const cgSearch = await fetchHttpsJson(`https://api.coingecko.com/api/v3/search?query=${encodeURIComponent(sym)}`, 3500);
    if (cgSearch && Array.isArray(cgSearch.coins) && cgSearch.coins.length > 0) {
      const match = cgSearch.coins.find((c: any) => c.symbol && c.symbol.toUpperCase() === sym) || cgSearch.coins[0];
      if (match && match.id) {
        const detail = await fetchHttpsJson(
          `https://api.coingecko.com/api/v3/simple/price?ids=${encodeURIComponent(match.id)}&vs_currencies=usd&include_24hr_change=true&include_market_cap=true&include_24hr_vol=true`,
          3500
        );
        if (detail && detail[match.id]) {
          const item = detail[match.id];
          const p = item.usd;
          const chg = item.usd_24h_change;
          if (typeof p === 'number' && p > 0) {
            return {
              source: 'coingecko',
              priceUsd: p,
              change24hPct: typeof chg === 'number' ? parseFloat(chg.toFixed(2)) : 0,
              marketCapUsd: item.usd_market_cap,
              volumeUsd: item.usd_24h_vol
            };
          }
        }
      }
    }
  } catch (err) {
    console.warn(`CoinGecko lookup failed for ${sym}:`, err);
  }

  // 3. Fallback: use realistic default from catalog or estimate
  return {
    source: 'fallback',
    priceUsd: defaultPrice > 0 ? defaultPrice : 1.0,
    change24hPct: 0.5
  };
}

/**
 * Format price values according to magnitude (e.g. micro-caps vs large-caps)
 */
export function formatPriceNumber(val: number): number {
  if (val >= 100) return Number(val.toFixed(2));
  if (val >= 1) return Number(val.toFixed(4));
  if (val >= 0.0001) return Number(val.toFixed(6));
  return Number(val.toFixed(8));
}

/**
 * Calculate dynamic support, resistance, and targets from real current price
 */
export function calculateDynamicLevels(
  currentPriceUsd: number,
  high24h?: number,
  low24h?: number
) {
  const round = formatPriceNumber;

  // Immediate support: slightly below current price, anchored by 24h low if available
  const immediateSupport = round(
    low24h && low24h > 0 && low24h < currentPriceUsd 
      ? Math.max(low24h * 0.98, currentPriceUsd * 0.93)
      : currentPriceUsd * 0.94
  );

  // Major institutional floor
  const majorFloor = round(currentPriceUsd * 0.81);

  // Primary resistance: capped near 24h high or ~8-12% above current price
  const primaryResistance = round(
    high24h && high24h > currentPriceUsd 
      ? Math.min(high24h * 1.03, currentPriceUsd * 1.12)
      : currentPriceUsd * 1.09
  );

  // Breakout cycle target
  const breakoutTarget = round(currentPriceUsd * 1.28);

  // 90-day and 1-year estimates
  const high90d = round(high24h ? Math.max(high24h * 1.18, currentPriceUsd * 1.25) : currentPriceUsd * 1.35);
  const low90d = round(low24h ? Math.min(low24h * 0.85, currentPriceUsd * 0.72) : currentPriceUsd * 0.70);
  const high1y = round(high90d * 1.35);
  const low1y = round(low90d * 0.75);

  return {
    immediateSupport,
    majorFloor,
    primaryResistance,
    breakoutTarget,
    high90d,
    low90d,
    high1y,
    low1y
  };
}

/**
 * Generate 90-day chart data ending with the exact current price and coin/BTC ratio
 */
export function generateChartData(
  currentPriceUsd: number,
  priceBtc: number
): Array<{ date: string; priceUsd: number; priceBtc: number; volumeUsd: number }> {
  const points = [];
  const now = new Date();
  let tempUsd = currentPriceUsd * 0.82;
  let tempBtc = priceBtc * 0.88;

  for (let i = 90; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 24 * 60 * 60 * 1000);
    const dateStr = d.toISOString().split('T')[0];
    const noise = Math.sin(i * 0.28) * 0.035 + ((i % 5 - 2) * 0.012);
    tempUsd = tempUsd * (1 + (i < 30 ? 0.005 : 0.002) + noise);
    tempBtc = tempBtc * (1 + (i < 45 ? 0.0025 : -0.001) + noise * 0.5);

    if (i === 0) {
      tempUsd = currentPriceUsd;
      tempBtc = priceBtc;
    }

    points.push({
      date: dateStr,
      priceUsd: formatPriceNumber(tempUsd),
      priceBtc: Number(tempBtc.toFixed(8)),
      volumeUsd: Math.round((currentPriceUsd * 40000000) * (0.8 + Math.abs(noise) * 4))
    });
  }
  return points;
}
